/* uart_chat_hal: the CHIP_EM "chat" protocol on an STM32F405ZG, written against ST's official STM32CubeF4 HAL.
 *
 * Clock:  HSE 8 MHz -> PLL (M 8, N 336, P 2, Q 7) -> SYSCLK = HCLK = 168 MHz, APB1 = 42 MHz, APB2 = 84 MHz,
 *         FLASH latency 5 WS, PWR regulator scale 1 (SystemClock_Config, as generated by STM32CubeMX).
 * Tick:   HAL_Init() -> SysTick 1 kHz (HAL_GetTick / HAL_Delay).
 * UART:   USART1 115200 8N1 on PA9 (TX, AF7) / PA10 (RX, AF7).  TX blocking (HAL_UART_Transmit), RX interrupt
 *         driven one byte at a time (HAL_UART_Receive_IT, re-armed in HAL_UART_RxCpltCallback) into a ring.
 * Pins:   PB0 = LED (toggles on every PONG received), PB1 = "peer seen" (high after a HELLO line).
 *
 * Protocol (shared with the C2000 side, firmware/samples_c2000/uart_chat):
 *   boot: "HELLO STM32\r\n";  every 5 ms: "PING <n>\r\n" (n = 1, 2, ...);
 *   rx "PING <n>" -> tx "PONG <n>\r\n";  rx "PONG <n>" -> toggle PB0, pongs++;  rx "HELLO <x>" -> peer_seen, PB1 = 1
 *   (the first HELLO received is answered with our HELLO once, for a peer that booted after we sent ours);
 *   lines end with "\n" ("\r" is dropped), unknown lines and empty lines are ignored.
 */
#include "stm32f4xx_hal.h"

#define PING_PERIOD_MS 5u
#define RX_RING 256u
#define LINE_MAX 48u
#define HELLO "HELLO STM32\r\n"

UART_HandleTypeDef huart1;

static uint8_t rx_byte;
static volatile uint8_t rx_ring[RX_RING];
static volatile uint32_t rx_head;          /* written by the USART1 IRQ */
static uint32_t rx_tail;                   /* read by the main loop */

volatile uint32_t pongs;                   /* PONG lines received */
volatile uint32_t pings_rx;                /* PING lines received (answered) */
volatile uint32_t pings_tx;                /* last PING number sent */
volatile uint32_t peer_seen;               /* a HELLO line arrived */
volatile uint32_t uart_errors;

static void SystemClock_Config(void);
static void GPIO_Init(void);
static void USART1_Init(void);
static void Error_Handler(void);

/* ------------------------------------------------------------------ small string helpers (no libc) */
static uint32_t put_u32(char *p, uint32_t v)
{
    char tmp[10];
    uint32_t n = 0, i = 0;
    do {
        tmp[n++] = (char)('0' + v % 10u);
        v /= 10u;
    } while (v);
    while (n)
        p[i++] = tmp[--n];
    return i;
}

static int starts_with(const char *s, uint32_t len, const char *pfx)
{
    uint32_t i = 0;
    for (; pfx[i]; i++)
        if (i >= len || s[i] != pfx[i])
            return 0;
    return 1;
}

static int parse_u32(const char *s, uint32_t len, uint32_t *out)
{
    uint32_t v = 0;
    if (len == 0)
        return 0;
    for (uint32_t i = 0; i < len; i++) {
        if (s[i] < '0' || s[i] > '9')
            return 0;
        v = v * 10u + (uint32_t)(s[i] - '0');
    }
    *out = v;
    return 1;
}

static void send_str(const char *s, uint32_t len)
{
    HAL_UART_Transmit(&huart1, (const uint8_t *)s, (uint16_t)len, 100);
}

static void send_word_num(const char *word, uint32_t n)        /* "<word> <n>\r\n" */
{
    char buf[24];
    uint32_t i = 0;
    while (word[i]) {
        buf[i] = word[i];
        i++;
    }
    buf[i++] = ' ';
    i += put_u32(buf + i, n);
    buf[i++] = '\r';
    buf[i++] = '\n';
    send_str(buf, i);
}

/* ------------------------------------------------------------------ protocol */
static void handle_line(const char *s, uint32_t len)
{
    uint32_t n;
    if (starts_with(s, len, "PING ") && parse_u32(s + 5, len - 5, &n)) {
        pings_rx++;
        send_word_num("PONG", n);
    } else if (starts_with(s, len, "PONG ") && parse_u32(s + 5, len - 5, &n)) {
        pongs++;
        HAL_GPIO_TogglePin(GPIOB, GPIO_PIN_0);
    } else if (starts_with(s, len, "HELLO ")) {
        /* A peer that boots after us (the F28232 waits ~6.6 ms for its PLL) missed our boot HELLO: answer its
         * first HELLO with ours once.  Terminates even if the peer does the same (only the first HELLO counts). */
        if (!peer_seen)
            send_str(HELLO, sizeof HELLO - 1);
        peer_seen = 1;
        HAL_GPIO_WritePin(GPIOB, GPIO_PIN_1, GPIO_PIN_SET);
    }
    /* anything else: ignored */
}

static void poll_rx(void)
{
    static char line[LINE_MAX];
    static uint32_t len;
    static int overflow;
    while (rx_tail != rx_head) {
        char c = (char)rx_ring[rx_tail % RX_RING];
        rx_tail++;
        if (c == '\r')
            continue;
        if (c == '\n') {
            if (!overflow && len)
                handle_line(line, len);
            len = 0;
            overflow = 0;
        } else if (len < LINE_MAX) {
            line[len++] = c;
        } else {
            overflow = 1;
        }
    }
}

int main(void)
{
    HAL_Init();
    SystemClock_Config();
    GPIO_Init();
    USART1_Init();

    if (HAL_UART_Receive_IT(&huart1, &rx_byte, 1) != HAL_OK)
        Error_Handler();

    HAL_Delay(1);                          /* >= 1 ms with the TX line idle high before the first frame */
    send_str(HELLO, sizeof HELLO - 1);

    uint32_t next = HAL_GetTick() + PING_PERIOD_MS;
    for (;;) {
        poll_rx();
        if ((int32_t)(HAL_GetTick() - next) >= 0) {
            next += PING_PERIOD_MS;
            send_word_num("PING", ++pings_tx);
        }
        __WFI();                           /* woken by SysTick (1 ms) or USART1 RXNE */
    }
}

/* ------------------------------------------------------------------ HAL callbacks and init */
void HAL_UART_RxCpltCallback(UART_HandleTypeDef *huart)
{
    if (huart->Instance == USART1) {
        rx_ring[rx_head % RX_RING] = rx_byte;
        rx_head++;
        HAL_UART_Receive_IT(&huart1, &rx_byte, 1);
    }
}

void HAL_UART_ErrorCallback(UART_HandleTypeDef *huart)
{
    if (huart->Instance == USART1) {
        uart_errors++;
        HAL_UART_Receive_IT(&huart1, &rx_byte, 1);
    }
}

void HAL_UART_MspInit(UART_HandleTypeDef *huart)
{
    if (huart->Instance == USART1) {
        GPIO_InitTypeDef g = {0};
        __HAL_RCC_USART1_CLK_ENABLE();
        __HAL_RCC_GPIOA_CLK_ENABLE();
        g.Pin = GPIO_PIN_9 | GPIO_PIN_10;
        g.Mode = GPIO_MODE_AF_PP;
        g.Pull = GPIO_PULLUP;
        g.Speed = GPIO_SPEED_FREQ_VERY_HIGH;
        g.Alternate = GPIO_AF7_USART1;
        HAL_GPIO_Init(GPIOA, &g);
        HAL_NVIC_SetPriority(USART1_IRQn, 5, 0);
        HAL_NVIC_EnableIRQ(USART1_IRQn);
    }
}

static void USART1_Init(void)
{
    huart1.Instance = USART1;
    huart1.Init.BaudRate = 115200;
    huart1.Init.WordLength = UART_WORDLENGTH_8B;
    huart1.Init.StopBits = UART_STOPBITS_1;
    huart1.Init.Parity = UART_PARITY_NONE;
    huart1.Init.Mode = UART_MODE_TX_RX;
    huart1.Init.HwFlowCtl = UART_HWCONTROL_NONE;
    huart1.Init.OverSampling = UART_OVERSAMPLING_16;
    if (HAL_UART_Init(&huart1) != HAL_OK)
        Error_Handler();
}

static void GPIO_Init(void)
{
    GPIO_InitTypeDef g = {0};
    __HAL_RCC_GPIOB_CLK_ENABLE();
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_0 | GPIO_PIN_1, GPIO_PIN_RESET);
    g.Pin = GPIO_PIN_0 | GPIO_PIN_1;
    g.Mode = GPIO_MODE_OUTPUT_PP;
    g.Pull = GPIO_NOPULL;
    g.Speed = GPIO_SPEED_FREQ_LOW;
    HAL_GPIO_Init(GPIOB, &g);
}

/* As generated by STM32CubeMX for an 8 MHz crystal and 168 MHz SYSCLK. */
static void SystemClock_Config(void)
{
    RCC_OscInitTypeDef osc = {0};
    RCC_ClkInitTypeDef clk = {0};

    __HAL_RCC_PWR_CLK_ENABLE();
    __HAL_PWR_VOLTAGESCALING_CONFIG(PWR_REGULATOR_VOLTAGE_SCALE1);

    osc.OscillatorType = RCC_OSCILLATORTYPE_HSE;
    osc.HSEState = RCC_HSE_ON;
    osc.PLL.PLLState = RCC_PLL_ON;
    osc.PLL.PLLSource = RCC_PLLSOURCE_HSE;
    osc.PLL.PLLM = 8;
    osc.PLL.PLLN = 336;
    osc.PLL.PLLP = RCC_PLLP_DIV2;
    osc.PLL.PLLQ = 7;
    if (HAL_RCC_OscConfig(&osc) != HAL_OK)
        Error_Handler();

    clk.ClockType = RCC_CLOCKTYPE_HCLK | RCC_CLOCKTYPE_SYSCLK | RCC_CLOCKTYPE_PCLK1 | RCC_CLOCKTYPE_PCLK2;
    clk.SYSCLKSource = RCC_SYSCLKSOURCE_PLLCLK;
    clk.AHBCLKDivider = RCC_SYSCLK_DIV1;
    clk.APB1CLKDivider = RCC_HCLK_DIV4;
    clk.APB2CLKDivider = RCC_HCLK_DIV2;
    if (HAL_RCC_ClockConfig(&clk, FLASH_LATENCY_5) != HAL_OK)
        Error_Handler();
}

static void Error_Handler(void)
{
    __disable_irq();
    for (;;) { }
}

/* ------------------------------------------------------------------ interrupt handlers */
void SysTick_Handler(void)
{
    HAL_IncTick();
}

void USART1_IRQHandler(void)
{
    HAL_UART_IRQHandler(&huart1);
}
